#include <stdio.h>
#include <ctype.h>
#include <errno.h>
#include <stdlib.h>

static int read_numbers(int values[], const int maxima[], int count);

int main(void)
{
    int values[2];
    const int maxima[] = {1000, 1000};
    if (!read_numbers(values, maxima, 2) || values[1] == 0) {
        puts("invalid");
        return 0;
    }
    int total = values[0];
    int per_roll = values[1];
    int rolls = total / per_roll;
    int left = total % per_roll;
    printf("%d %d\n", rolls, left);
    return 0;
}

static int read_numbers(int values[], const int maxima[], int count)
{
    char line[80];
    int length = 0;
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == 0 || length == (int)sizeof line - 1) { return 0; }
        line[length++] = (char)ch;
    }
    if (ferror(stdin)) { return 0; }
    line[length] = '\0';
    char *cursor = line;
    for (int i = 0; i < count; ++i) {
        char *end;
        errno = 0;
        long value = strtol(cursor, &end, 10);
        if (end == cursor || errno == ERANGE || value < 0 || value > maxima[i]) {
            return 0;
        }
        if (i + 1 < count && !isspace((unsigned char)*end)) { return 0; }
        values[i] = (int)value;
        cursor = end;
    }
    while (isspace((unsigned char)*cursor)) { ++cursor; }
    return *cursor == '\0';
}

